actions.script:
if (!ec.entity.isEntityDefined('zenith.erp.saas.SaasTenant')) return
def org = scope.organizationPartyId
def kotPlan = ec.entity.find('zenith.erp.saas.SaasTenant')
    .condition('organizationPartyId',org).condition('planId','KOT').disableAuthz().useCache(true).count() > 0
if (!kotPlan) return
// Count across the organization before applying any selected shop or cashier assignment.
def counters = ec.entity.find('zenith.erp.pos.PosTerminal')
    .condition('organizationPartyId',org).condition('isActive','Y')
    .selectField('terminalId').limit(2).disableAuthz().list()
scope.kotCounterId = counters.size() == 1 ? counters[0].terminalId : null
scope.kotCounterConfigured = scope.kotCounterId != null
if (scope.terminalRestricted) scope.allowedTerminalIds = scope.allowedTerminalIds.findAll { it == scope.kotCounterId }
else scope.allowedTerminalIds = scope.kotCounterConfigured ? [scope.kotCounterId] : []
scope.terminalRestricted = true
if (terminalId && !scope.allowedTerminalIds.contains(terminalId)) {
    scope.allowed = false
    ec.message.addError('KOT Plan allows billing at one active counter. Ask your administrator to check the counter setup.')
}

def row=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sessionId).one()
def counter=row ? ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',row.terminalId).one() : null
def shop=ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call().activeShopId
def facility=counter?.facilityId ? ec.entity.find('mantle.facility.Facility').condition('facilityId',counter.facilityId).one() : null
if(scope.kotCounterConfigured == false || (scope.kotCounterId && counter?.terminalId != scope.kotCounterId)) {
    ec.message.addError('KOT Plan allows billing at one active counter. Ask your administrator to check the counter setup.'); return
}
if(row?.statusId!='PsOpen' || row.operatorPartyId!=ec.user.userAccount?.partyId || counter?.isActive!='Y' ||
    counter.organizationPartyId!=scope.organizationPartyId || facility?.ownerPartyId!=scope.organizationPartyId || (shop && counter.facilityId!=shop)) {
    ec.message.addError('Choose your open terminal session in this shop.'); return
}
session=row.getMap(); terminal=counter.getMap()

def uri = ec.web?.request?.requestURI ?: ''
def moduleId = uri ==~ /\/(apps|qapps)\/zenith\/kot\/.+/ ? 'kot' : 'pos'
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId', moduleId).call()
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (access?.canWrite != true || !org || org == '_NA_') {
    ec.message.addError('Write access and an active shop are required for this kitchen workflow.')
    return
}
def key = 'KOT_' + org
def counter = ec.entity.find('zenith.erp.pos.PosBillSequence').condition('seqKey', key).forUpdate(true).one()
int nextNum
if (counter) {
    nextNum = ((counter.lastNumber ?: 1000) as int) + 1
    counter.set('lastNumber', nextNum).update()
} else {
    int maxNum = 1000
    def prior = ec.entity.find('zenith.erp.pos.KitchenOrderTicket')
        .condition('organizationPartyId', org).selectField('kotNumber').list()
    prior.each { row ->
        def n = row.kotNumber?.toString()
        if (n ==~ /\d+/) maxNum = Math.max(maxNum, n.toInteger())
    }
    nextNum = maxNum + 1
    try {
        ec.service.sync().name('create#zenith.erp.pos.PosBillSequence')
            .parameters([seqKey:key, lastNumber:nextNum]).call()
    } catch (Exception ignored) {
        def current = ec.entity.find('zenith.erp.pos.PosBillSequence')
            .condition('seqKey', key).forUpdate(true).one()
        nextNum = ((current.lastNumber ?: maxNum) as int) + 1
        current.set('lastNumber', nextNum).update()
    }
}
kotNumber = String.valueOf(nextNum)

table = null
if (tableId) {
    def row = tableId.toString().contains('*') ? null : ec.entity.find('zenith.erp.pos.RestaurantTable').condition('tableId',tableId).forUpdate(true).one()
    def facility = row ? ec.entity.find('mantle.facility.Facility').condition('facilityId',row.facilityId).one() : null
    if (!row || facility?.ownerPartyId != scope.organizationPartyId) { ec.message.addError('Select a table in this shop.'); return }
    table = row.getMap()
} else if (tableNumber) {
    def facilities=ec.entity.find('mantle.facility.Facility').condition('ownerPartyId',scope.organizationPartyId).list()*.facilityId
    def matches=facilities ? ec.entity.find('zenith.erp.pos.RestaurantTable').condition('facilityId','in',facilities).condition('tableNumber',tableNumber).forUpdate(true).list() : []
    if(matches.size()>1) { ec.message.addError('Select the table and its facility; this number exists in more than one facility.'); return }
    if(matches) table=matches[0].getMap()
}

def uri = ec.web?.request?.requestURI ?: ''
def moduleId = uri ==~ /\/(apps|qapps)\/zenith\/kot\/.+/ ? 'kot' : 'pos'
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId', moduleId).call()
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (access?.canWrite != true || !org || org == '_NA_') {
    ec.message.addError('Write access and an active shop are required for this kitchen workflow.')
    return
}
def kot = ec.entity.find('zenith.erp.pos.KitchenOrderTicket')
    .condition('kotId', kotId).forUpdate(true).one()
if (!kot || kot.organizationPartyId != org) {
    ec.message.addError('Kitchen order not found in this shop.')
    return
}
def allowed = [KotNew:['KotPreparing', 'KotCancelled'],
               KotPreparing:['KotReady', 'KotCancelled'],
               KotReady:['KotServed']]
if (!(statusId in (allowed[kot.statusId] ?: []))) {
    ec.message.addError('This kitchen order can no longer move to that status. Refresh the page.')
    return
}
kot.set('statusId', statusId).update()
// A served order can release the table only after its bill is completed.
if (kot.tableId && statusId in ['KotCancelled','KotServed']) {
    def billed = statusId=='KotServed' && kot.transactionId &&
        ec.entity.find('zenith.erp.pos.PosTransaction').condition([transactionId:kot.transactionId,
            organizationPartyId:org,statusId:'PtCompleted']).count()
    if (statusId=='KotServed' && !billed) return
    def table=ec.entity.find('zenith.erp.pos.RestaurantTable').condition('tableId',kot.tableId).forUpdate(true).one()
    def facility=table ? ec.entity.find('mantle.facility.Facility').condition('facilityId',table.facilityId).one() : null
    def active=ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('organizationPartyId',org)
        .condition('tableId',kot.tableId).condition('statusId','in',['KotNew','KotPreparing','KotReady']).count()
    if (billed && !active) active=ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('organizationPartyId',org)
        .condition('tableId',kot.tableId).condition('transactionId',null).condition('statusId','in',['KotDraft','KotServed']).count()
    if (facility?.ownerPartyId==org && !active && !table.currentTransactionId && table.statusId=='TblOccupied') table.set('statusId','TblAvailable').update()
}

def uri = ec.web?.request?.requestURI ?: ''
def moduleId = uri ==~ /\/(apps|qapps)\/zenith\/kot\/.+/ ? 'kot' : 'pos'
def access = ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
    .parameter('moduleId', moduleId).call()
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (access?.canWrite != true || !org || org == '_NA_') {
    ec.message.addError('Write access and an active shop are required for this kitchen workflow.')
    return
}
def kot = ec.entity.find('zenith.erp.pos.KitchenOrderTicket')
    .condition('kotId', kotId).forUpdate(true).one()
if (!kot || kot.organizationPartyId != org) {
    ec.message.addError('Kitchen order not found in this shop.')
    return
}
printCount=((kot.printCount ?: 0) as int)+1
kot.set('printCount',printCount).update()
